package com.yihe.framework.ehr;
import java.util.*;import java.time.*;import java.nio.file.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import static com.yihe.framework.ehr.EhrAccess.*;import static com.yihe.framework.ehr.EhrService.*;
/** Shared database integration checks: every mutation is rolled back; model calls are disabled. */
@SuppressWarnings("unchecked") public class PsychologyCollaborationChecks {
 static int n;static void check(boolean b,String s){if(!b)throw new AssertionError(s);System.out.println("PASS "+(++n)+" "+s);}
 static void denied(Runnable run,String s){boolean failed=false;try{run.run();}catch(EhrException e){failed=true;}check(failed,s);}
 public static void main(String[]args)throws Exception{
  Map<String,Object>config=new ObjectMapper().readValue(Files.readAllBytes(Paths.get(args[0])),Map.class);DriverManagerDataSource ds=new DriverManagerDataSource(str(config.get("url")),str(config.get("username")),str(config.get("password")));EhrRepository db=new EhrRepository(ds);EhrService ehr=new EhrService(db);QuestionnaireService qs=new QuestionnaireService(db,ehr);QuestionnaireWorkflow wf=new QuestionnaireWorkflow(db,ehr,qs);WorkerCollaborationService orders=new WorkerCollaborationService(db,ehr,qs);PsychologyCoordinator psych=new PsychologyCoordinator(db,ehr,wf,qs,orders,new DigitalWorkerModelClient());
  new TransactionTemplate(new DataSourceTransactionManager(ds)).execute(tx->{try{
   Map<String,Object>q=db.one("SELECT * FROM a_questionnaires WHERE questionnaire_id=?","015ffce8-eb1d-5cb1-ab76-6ddae6588dbf");String scope=str(q.get("scope_code")),mode=str(q.get("data_mode"));EhrActor a=new EhrActor(str(q.get("updated_by")),scope.substring(4),mode,true,false);String record=str(db.one("SELECT r.record_id"+ehr.baseSql()+" LIMIT 1",scope,mode).get("record_id"));String due=LocalDateTime.now(ZoneId.of("Asia/Shanghai")).plusDays(3).withNano(0).toString();
   check(WorkerCollaborationService.route("care","plan","psychological_plan"),"Psychology transfers to plan");check(!WorkerCollaborationService.route("care","follow","followup_execution"),"Psychology cannot dispatch execution");check(WorkerCollaborationService.route("plan","follow","followup_execution"),"Only plan assigns followup");
   Map<String,Object>body=map("requestKey",id(),"sourceWorker","archive","targetWorker","care","kind","psychological_assessment","recordId",record,"title","Rollback psychological assessment","instructions","Test only","priority","normal","dueAt",due,"dispatch",true,"payload",Collections.emptyMap());Map<String,Object>created=(Map<String,Object>)orders.create(a,body);String oid=str(created.get("id"));check(created.equals(orders.create(a,body)),"Creation idempotent");
   orders.act(a,oid,map("requestKey",id(),"version",1,"actingWorker","care","action","claim","note","Claim in rollback test"));denied(()->orders.act(a,oid,map("requestKey",id(),"version",1,"actingWorker","care","action","claim","note","Duplicate claim")),"Stale or concurrent claim rejected");
   orders.act(a,oid,map("requestKey",id(),"version",2,"actingWorker","care","action","start","note","Started"));orders.act(a,oid,map("requestKey",id(),"version",3,"actingWorker","care","action","submit","note","Results submitted","result",map("summary","Test evidence")));
   denied(()->orders.act(a,oid,map("requestKey",id(),"version",4,"actingWorker","care","action","accept","note","Invalid self acceptance","professionalConfirmed",true)),"Receiver cannot accept own result");orders.act(a,oid,map("requestKey",id(),"version",4,"actingWorker","archive","action","return","note","Needs correction"));orders.act(a,oid,map("requestKey",id(),"version",5,"actingWorker","care","action","start","note","Correction"));orders.act(a,oid,map("requestKey",id(),"version",6,"actingWorker","care","action","submit","note","Corrected","result",map("summary","Verified")));orders.act(a,oid,map("requestKey",id(),"version",7,"actingWorker","archive","action","accept","note","Accepted","professionalConfirmed",true));check("completed".equals(orders.owned(a,oid,false).get("order_state")),"Return and acceptance lifecycle complete");
   check(((List<?>)((Map<?,?>)orders.detail(a,oid)).get("events")).size()==8,"Every transition audited");
   denied(()->orders.detail(new EhrActor(a.user,"other-unit",mode,true,false),oid),"Cross organisation denied");denied(()->orders.detail(new EhrActor(a.user,scope.substring(4),mode,false,false),oid),"Manager cannot access personal psychology");denied(()->orders.detail(new EhrActor(a.user,scope.substring(4),mode,true,true),oid),"Mobile cannot access staff work orders");
   String release=id(),assignment=id(),response=id();db.insert("a_questionnaire_releases",map("release_id",release,"scope_code",scope,"data_mode",mode,"questionnaire_id",q.get("questionnaire_id"),"revision",987,"document_json",q.get("document_json"),"release_status","active","published_by",a.user,"published_at",now()));db.insert("a_questionnaire_assignments",map("assignment_id",assignment,"release_id",release,"record_id",record,"scope_code",scope,"data_mode",mode,"assigned_by",a.user,"assigned_at",now()));db.insert("a_questionnaire_responses",map("response_id",response,"assignment_id",assignment,"scope_code",scope,"data_mode",mode,"answers_json","{}","total_score",0,"submitted_by",a.user,"submission_channel","proxy","source_description","Rollback only","submitted_at",now()));db.insert("a_questionnaire_processing",map("response_id",response,"scope_code",scope,"data_mode",mode,"score_json",ehr.encode(map("urgent",true,"risk","high","scales",Collections.emptyList())),"ai_state","disabled","alert_state","urgent_review","created_at",now(),"updated_at",now()));
   PsychologyCoordinator.responseEvent(db,ehr,a,response);String iid=PsychologyCoordinator.stable(scope+":"+mode+":response:"+response);Map<String,Object>item=psych.item(a,iid,false);long version=num(item.get("row_version"));PsychologyCoordinator.responseEvent(db,ehr,a,response);check(version==num(psych.item(a,iid,false).get("row_version")),"Reconciliation does not churn versions");check(num(item.get("emergency"))==1,"Urgent signal immediately creates doctor task");
   denied(()->psych.act(a,iid,map("requestKey",id(),"version",version,"action","resolve","note","No human response")),"Urgent task cannot auto close");
   Map<String,Object>transfer=map("requestKey",id(),"version",version,"dueAt",due,"concerns","Review management needs","professionalConfirmed",true);denied(()->psych.handoff(a,iid,transfer),"Unreviewed urgent answer cannot transfer");
   psych.act(a,iid,map("requestKey",id(),"version",version,"action","emergency_ack","contactConfirmed",true,"note","Doctor response initiated"));db.exec("UPDATE a_questionnaire_responses SET review_state='confirmed',risk_level='high',review_note='Reviewed in rollback test',reviewer=?,reviewed_at=UTC_TIMESTAMP(6) WHERE response_id=?",a.user,response);PsychologyCoordinator.responseEvent(db,ehr,a,response);transfer.put("requestKey",id());transfer.put("version",psych.item(a,iid,false).get("row_version"));Map<String,Object>handoff=(Map<String,Object>)psych.handoff(a,iid,transfer);check(handoff.equals(psych.handoff(a,iid,transfer)),"Assessment handoff idempotent");Map<String,Object>order=orders.owned(a,str(handoff.get("orderId")),false);check("plan".equals(order.get("target_worker"))&&"care".equals(order.get("source_worker")),"Frozen assessment dispatched only to plan worker");check(db.count("SELECT COUNT(*) FROM a_worker_orders WHERE parent_id=? AND target_worker='follow'",order.get("order_id"))==0,"Handoff never creates followup execution");
   denied(()->psych.feedback(a,str(handoff.get("id")),map("requestKey",id(),"version",1,"actingWorker","plan","state","completed","note","Not actually received")),"Cannot fabricate completion before claim");
   orders.act(a,str(order.get("order_id")),map("requestKey",id(),"version",1,"actingWorker","plan","action","claim","note","Plan receives assessment"));psych.feedback(a,str(handoff.get("id")),map("requestKey",id(),"version",1,"actingWorker","plan","state","received","note","Needs doctor authorised retest","reassessmentRequirement","Review whether retest is appropriate"));check(db.count("SELECT COUNT(*) FROM a_psych_worker_items WHERE record_id=? AND item_kind='reassessment_request'",record)>0,"Plan retest feedback creates doctor review item, not automatic questionnaire");
   psych.overview(a);psych.people(a,Collections.singletonMap("limit","1"));psych.timeline(a,record);orders.list(a,Collections.singletonMap("tab","sent"));check(true,"Scoped summary, people, timeline and work order queries pass");
   String template=id();Map<String,Object>sourceDoc=(Map<String,Object>)ehr.decode(q.get("document_json")),templateDoc=new LinkedHashMap<>((Map<String,Object>)sourceDoc.get("centerConfig"));templateDoc.put("id",template);templateDoc.put("name","Rollback isolated assessment template");templateDoc.remove("version");wf.savePlans(a,map("requestKey",id(),"version",wf.state(a,false).get("row_version"),"plans",Arrays.asList(templateDoc)));
   Map<String,Object>doc=map("title","Rollback scheduling only","questionnaireId",template,"selection","random","records",Arrays.asList(record),"intervalDays",30,"minimumGapDays",30,"durationDays",14,"sampleSize",1,"nextRunAt",due,"purpose","Authorised rollback verification","aiEnabled",false);
   Map<String,Object>policyBody=map("requestKey",id(),"document",doc,"enabled",false);Map<String,Object>savedPolicy=(Map<String,Object>)psych.savePolicy(a,policyBody);check(savedPolicy.equals(psych.savePolicy(a,policyBody)),"Policy save idempotent");
   String policyId=str(savedPolicy.get("id"));denied(()->psych.runPolicy(a,policyId,map("requestKey",id(),"version",1)),"Disabled policy never dispatches");
   Map<String,Object>activeDoctor=db.one("SELECT user_code FROM yh_user_reginfo WHERE Org_Code=? AND User_Type=4 AND lock_flag=2 LIMIT 1",scope.substring(4));check(activeDoctor!=null,"Policy requires an active doctor in same unit");db.exec("UPDATE a_psych_worker_policies SET enabled=1,approved_by=? WHERE policy_id=?",activeDoctor.get("user_code"),policyId);
   Map<String,Object>run=(Map<String,Object>)psych.runPolicy(a,policyId,map("requestKey",id(),"version",1));check(num(run.get("assigned"))==1,"Approved scheduling creates one real assignment inside rollback transaction");
   Map<String,Object>second=(Map<String,Object>)psych.runPolicy(a,policyId,map("requestKey",id(),"version",2));check(num(second.get("assigned"))==0,"Repeated run respects same-template minimum interval");
  }finally{tx.setRollbackOnly();}return null;});System.out.println("ALL "+n+" CHECKS PASSED; ROLLED BACK; NO EXTERNAL AI CALLS");
 }
}
